USE [olist_dwh];
GO

--===========================================================================================
-- i am creating the customer dimension in the gold schema.
-- customer_key will be the surrogate key generated by sql server.
-- customer_unique_id will remain the business key used to identify each customer.
-- geography_key will reference the geography dimension using its surrogate key.
-- city and state will be tracked to preserve historical changes using scd type 2.
-- the valid_from, valid_to and is_current columns will help me manage each customer version.
--===========================================================================================

IF OBJECT_ID('[gold].[dim_customer]', 'U') IS NULL
BEGIN
    CREATE TABLE [gold].[dim_customer]
    (
        customer_key INT IDENTITY(1,1) NOT NULL,
        customer_unique_id VARCHAR(50) NOT NULL,
        geography_key INT NOT NULL,
        customer_city NVARCHAR(255) NULL,
        customer_state NVARCHAR(255) NULL,
        valid_from DATETIME2(7) NULL,
        valid_to DATETIME2(7) NULL,
        is_current BIT NOT NULL,

        CONSTRAINT PK_dim_customer
            PRIMARY KEY (customer_key)
    );
END;
GO


--========================================================================
-- i am creating a filtered unique index to ensure that each customer
-- can only have one current record in the dimension.
-- historical records are still allowed because they have is_current = 0.
--========================================================================

IF NOT EXISTS
(
    SELECT 1
    FROM sys.indexes
    WHERE name = 'UX_dim_customer_current'
      AND object_id = OBJECT_ID('[gold].[dim_customer]')
)
BEGIN
    CREATE UNIQUE NONCLUSTERED INDEX UX_dim_customer_current
    ON gold.dim_customer (customer_unique_id)
    WHERE is_current = 1;
END;
GO


--========================================================================
-- i am creating a foreign key relationship between the customer
-- dimension and the geography dimension.
-- geography_key will allow customers to reference their geographical
-- information without storing the same geographical details twice.
--========================================================================

IF NOT EXISTS
(
    SELECT 1
    FROM sys.foreign_keys
    WHERE name = 'FK_dim_customer_geography'
      AND parent_object_id = OBJECT_ID('[gold].[dim_customer]')
)
BEGIN
    ALTER TABLE gold.dim_customer

    ADD CONSTRAINT FK_dim_customer_geography

    FOREIGN KEY (geography_key)

    REFERENCES gold.dim_geography (geography_key);
END;
GO


--========================================================================
-- i am inserting an unknown customer record with customer_key = -1.
-- geography_key = -1 references the unknown geography record.
-- this record will be used when a customer cannot be matched.
-- identity_insert allows me to insert -1 manually.
-- the if not exists check prevents duplicate unknown records.
--========================================================================

IF NOT EXISTS
(
    SELECT 1
    FROM gold.dim_customer
    WHERE customer_key = -1
)
BEGIN

    SET IDENTITY_INSERT gold.dim_customer ON;

    INSERT INTO gold.dim_customer
    (
        customer_key,
        customer_unique_id,
        geography_key,
        customer_city,
        customer_state,
        valid_from,
        valid_to,
        is_current
    )
    VALUES
    (
        -1,
        'Unknown',
        -1,
        'Unknown',
        'Unknown',
        NULL,
        NULL,
        1
    );

    SET IDENTITY_INSERT gold.dim_customer OFF;

END;
GO